import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Label,
} from "reactstrap";
import { useState } from "react";
import { db, auth } from "../../firebase"; // Adjusted import path
import { collection, addDoc } from "firebase/firestore";
import AIHelper from "components/AIHelper"; // Placeholder for AI suggestions

const CarbonDataInput = () => {
  const [carbonData, setCarbonData] = useState({
    date: "",
    category: "",
    value: "",
    unit: "",
    carbonEmission: 0, // Stores calculated CO2 emissions
  });
  const [submitted, setSubmitted] = useState(false);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setCarbonData((prevData) => ({
      ...prevData,
      [name]: value,
      carbonEmission: name === "value" ? calculateCarbonEmissions(prevData.category, value) : prevData.carbonEmission,
    }));
  };

  // Calculate carbon emissions based on category
  const calculateCarbonEmissions = (category, value) => {
    value = parseFloat(value) || 0;

    switch (category) {
      case "Transport":
        return value * 2.31; // Example: 2.31 kg CO2 per liter of petrol
      case "Electricity":
        return value * 0.92; // Example: 0.92 kg CO2 per kWh
      case "Diet":
        return value * 3.5; // Example: 3.5 kg CO2 per kg of beef
      case "Waste":
        return value * 0.75; // Example: 0.75 kg CO2 per kg of waste
      default:
        return 0;
    }
  };

  // Get valid units dynamically based on category selection
  const getValidUnits = (category) => {
    switch (category) {
      case "Transport":
        return ["liters", "kg"];
      case "Electricity":
        return ["kWh"];
      case "Diet":
        return ["kg"];
      case "Waste":
        return ["kg"];
      default:
        return [];
    }
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!auth.currentUser) {
      alert("Please log in to save your data.");
      return;
    }

    try {
      await addDoc(collection(db, "carbon_logs"), {
        userId: auth.currentUser.uid,
        date: carbonData.date,
        category: carbonData.category,
        value: carbonData.value,
        unit: carbonData.unit,
        carbonEmission: carbonData.carbonEmission,
      });

      setSubmitted(true);
      setTimeout(() => setSubmitted(false), 2000); // Reset UI after saving
      setCarbonData({ date: "", category: "", value: "", unit: "", carbonEmission: 0 }); // Clear input fields
    } catch (error) {
      console.error("Error saving data:", error);
      alert("Failed to save data. Please try again.");
    }
  };

  return (
    <Container className="mt-5" fluid>
      <Row className="justify-content-center">
        <Col lg="8">
          <Card className="bg-secondary shadow">
            <CardHeader className="bg-white border-0 text-center">
              <h3 className="mb-0">Carbon Data Input</h3>
            </CardHeader>
            <CardBody>
              <Form onSubmit={handleSubmit}>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Date</Label>
                      <Input
                        type="date"
                        name="date"
                        value={carbonData.date}
                        onChange={handleChange}
                        required
                      />
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Activity Category</Label>
                      <Input
                        type="select"
                        name="category"
                        value={carbonData.category}
                        onChange={handleChange}
                        required
                      >
                        <option value="">Select Category</option>
                        <option value="Transport">Transport</option>
                        <option value="Electricity">Electricity</option>
                        <option value="Diet">Diet</option>
                        <option value="Waste">Waste Management</option>
                      </Input>
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Value</Label>
                      <Input
                        type="number"
                        name="value"
                        placeholder="Enter amount"
                        value={carbonData.value}
                        onChange={handleChange}
                        required
                      />
                    </FormGroup>
                  </Col>
                </Row>
                <Row>
                  <Col md="6">
                    <FormGroup>
                      <Label>Unit</Label>
                      <Input
                        type="select"
                        name="unit"
                        value={carbonData.unit}
                        onChange={handleChange}
                        disabled={!carbonData.category} // Disable until category is selected
                        required
                      >
                        <option value="">Select Unit</option>
                        {getValidUnits(carbonData.category).map((unit) => (
                          <option key={unit} value={unit}>{unit}</option>
                        ))}
                      </Input>
                    </FormGroup>
                  </Col>
                  <Col md="6">
                    <FormGroup>
                      <Label>Estimated CO₂ Emission (kg)</Label>
                      <Input
                        type="text"
                        value={carbonData.carbonEmission}
                        disabled
                      />
                    </FormGroup>
                  </Col>
                </Row>
                <Row className="text-center">
                  <Col>
                    <Button color="primary" type="submit">
                      Save Data
                    </Button>
                  </Col>
                </Row>
              </Form>
              {submitted && <p className="text-success text-center mt-3">Data saved successfully!</p>}
              <div className="mt-4 text-center">
                {carbonData.value && <AIHelper category={carbonData.category} value={carbonData.value} />}
              </div>
            </CardBody>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CarbonDataInput;
